function aiTenderPayload(data) {
  const cutoff = buyerHistoryDecisionDay(data, data?.tenderID);
  const prospectiveDocuments = (data?.documents || []).filter((d5) => {
    const published = new Date(d5?.datePublished), modified = new Date(d5?.dateModified || d5?.datePublished);
    return cutoff && Number.isFinite(published.getTime()) && Number.isFinite(modified.getTime()) && euro5ObservationDate(published) <= cutoff && euro5ObservationDate(modified) <= cutoff;
  });
  const reduced = {
    tenderID: data?.tenderID,
    title: data?.title,
    description: data?.description,
    procurementMethodType: data?.procurementMethodType,
    value: data?.value,
    items: data?.items,
    lots: (data?.lots || []).map(({ id, title, description, value }) => ({ id, title, description, value })),
    documents: prospectiveDocuments.map((d5) => ({
      title: d5?.title,
      documentType: d5?.documentType,
      format: d5?.format,
      datePublished: d5?.datePublished
    })),
    tenderPeriod: data?.tenderPeriod,
    enquiryPeriod: data?.enquiryPeriod,
    guarantee: data?.guarantee,
    criteria: data?.criteria,
    features: data?.features,
    milestones: data?.milestones
  };
  let s3 = JSON.stringify(reduced);
  if (s3.length > 7e4) s3 = s3.slice(0, 7e4);
  return s3;
}
